using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;

namespace AgentWorld
{
    /// Structured message Grace writes to shared memory; facts come from Unity, not from the model.
    [Serializable] public class SiteReport { public string location, nearby, reportedBy; public int freeSites; }
    /// One line of agent-to-agent dialogue. Text is generated by Llama; facts in the prompt come from Unity.
    [Serializable] public class AgentMessage { public string from, to, text; }
    [Serializable] public class MissionTask { public int id, attempts; public string agent, description, status = "Pending"; }

    [Serializable]
    public class MissionState
    {
        public string objective = "", status = "None", result = "";
        public int housesWanted, housesBuilt, farmsWanted, farmsBuilt;
        // Evaluation metrics (measured, never estimated).
        public string model = "", scenario = "";
        public int invalidResponses, recoveries, dialogueFailures;
        public float durationSeconds;
        public List<MissionTask> tasks = new List<MissionTask>();
        public List<SiteReport> sharedMemory = new List<SiteReport>();
        public List<string> log = new List<string>();
        public List<AgentMessage> conversation = new List<AgentMessage>();
        /// Grace's measurements from earlier missions. Only hints for planning: every mission re-measures before building.
        public List<SiteReport> knowledge = new List<SiteReport>();
    }

    /// Multi-agent mission: Ada (Llama) delegates -> Grace explores (Unity facts) -> Ada (Llama) picks sites -> Linus builds.
    /// The model makes the decisions; every decision is validated against live world state before anything moves.
    public static class MissionControl
    {
        public const int MaxExplore = 3, MaxHouses = 3, MaxFarms = 1, MaxRetries = 2, LogCap = 40;
        static readonly string[] Live = { "Planning", "Exploring", "Selecting", "Building" };

        [Serializable]
        public class Delegation
        {
            public string feasible; // "no" when the mission is beyond the team's abilities
            public List<string> explore = new List<string>();
            public int houses, farms;
            public string message;
            public bool Infeasible => (feasible ?? "").Trim().ToLowerInvariant() is "no" or "false";
        }
        [Serializable] public class SiteChoice { public List<string> build_at = new List<string>(); public string farm_at, reason; }

        public static MissionState State { get; private set; } = new MissionState();
        public static bool Running => cts != null;
        static CancellationTokenSource cts;
        static Action<string> output = _ => { };

        /// Raised once per mission with the final state (evaluation hooks in here).
        public static event Action<MissionState> Finished;
        static float startedAt;

        public static bool Start(string objective, Action<string> print, out string error) => Start(objective, print, null, out error);

        public static bool Start(string objective, Action<string> print, string scenario, out string error)
        {
            error = null;
            if (string.IsNullOrWhiteSpace(objective)) { error = "missão vazia"; return false; }
            if (Running) { error = "já existe uma missão em andamento (mission stop)"; return false; }
            var team = new[] { "assistant", "explorer", "builder" }.Select(AgentHub.Find).ToArray();
            if (team.Any(a => a == null)) { error = "Ada, Grace e Linus precisam estar na cena"; return false; }
            if (team.Any(a => a.Ai.Busy)) { error = "um agente está ocupado; use agent stop"; return false; }
            // The pipeline needs these skills; agents.json may have removed them.
            foreach (var (role, skill) in new[] { ("explorer", "move_to"), ("explorer", "inspect"), ("builder", "move_to"), ("builder", "build_house") })
                if (!AgentConfigs.Has(role, skill)) { error = $"{AgentHub.Find(role).displayName} não tem a skill '{skill}' (veja StreamingAssets/agents.json)"; return false; }

            State = new MissionState { objective = objective.Trim(), status = "Planning", knowledge = Merge(State.knowledge, State.sharedMemory), model = AgentHub.Llm.Model, scenario = scenario ?? "" };
            startedAt = Time.realtimeSinceStartup;
            output = print ?? (_ => { });
            cts = new CancellationTokenSource();
            _ = Run(team[0], team[1], team[2], cts.Token);
            return true;
        }

        public static void Stop() => cts?.Cancel();

        static async Task Run(NpcAgent ada, NpcAgent grace, NpcAgent linus, CancellationToken ct)
        {
            var builder = StructureBuilder.Instance;
            try
            {
                // 1. Ada delegates (Llama decision).
                ada.Ai.Show(AgentStatus.Thinking, "planejando a missão");
                Log($"[Ada] Pensando na missão (Llama: {AgentHub.Llm.Model})...");
                var known = State.knowledge.Count == 0 ? "" :
                    "Grace's earlier measurements (may be outdated; she will re-measure): " + string.Join(", ", State.knowledge.Select(r => $"{r.location}={r.freeSites} free")) + "\n";
                var plan = await AskJson<Delegation>("Ada", DelegationPrompt(), $"{AgentHub.WorldSummary()}{known}Mission: {State.objective}", ValidateDelegation, ct);
                ada.Ai.MarkDecision();
                if (plan.Infeasible)
                {
                    // Ada (Llama) judged the request outside the team's abilities: say so instead of pretending.
                    Log($"[Llama/Ada] missão não suportada: \"{plan.message}\"");
                    ada.Say(plan.message);
                    State.status = "Unsupported";
                    State.result = plan.message;
                    return;
                }
                State.housesWanted = plan.houses;
                State.farmsWanted = plan.farms;
                Log($"[Llama/Ada] explorar: {string.Join(", ", plan.explore)} | casas: {plan.houses} | fazendas: {plan.farms} | \"{plan.message}\"");
                if (!string.IsNullOrWhiteSpace(plan.message)) { ada.Say(plan.message); AddMessage("Ada", "Grace, Linus", plan.message); }
                ada.Ai.Show(AgentStatus.Idle, "aguardando relatórios");

                // 2. Grace explores; Unity measures real free space and writes it to shared memory.
                State.status = "Exploring";
                foreach (var loc in plan.explore)
                {
                    var task = AddTask("Grace", $"inspecionar {loc}");
                    var ok = await grace.Ai.Perform($"inspecionar {loc}", Actions(("move_to", loc), ("inspect", loc)), Log, ct);
                    ct.ThrowIfCancellationRequested();
                    if (!ok) { Finish(task, "Failed"); Log($"[Unity] Grace não conseguiu inspecionar {loc}: {grace.Ai.LastResult}"); continue; }
                    var lm = Landmark.Find(loc);
                    var report = new SiteReport
                    {
                        location = loc, reportedBy = "Grace",
                        freeSites = builder ? builder.CountSites(lm.transform.position) : 0,
                        nearby = string.Join(", ", Landmark.All.Where(l => l != lm && Vector2.Distance(l.transform.position, lm.transform.position) < 7f).Select(l => l.id).OrderBy(s => s)),
                    };
                    State.sharedMemory.Add(report);
                    ada.Ai.Remember($"Grace reported {loc}: {report.freeSites} free building sites");
                    Finish(task, "Done");
                    Log($"[Grace -> memória] {loc}: {report.freeSites} terrenos livres (perto: {(report.nearby == "" ? "nada" : report.nearby)})");
                }
                if (!State.sharedMemory.Any(r => r.freeSites > 0)) throw new Exception("nenhum local explorado tem espaço para construir");

                // 2b. Short team discussion (Llama), grounded in Grace's measured numbers; feeds Ada's decision.
                await Discuss(grace, linus, ct);

                // 3. Ada chooses sites from the reports (Llama decision, validated against capacity).
                State.status = "Selecting";
                ada.Ai.Show(AgentStatus.Thinking, "escolhendo terrenos");
                var choice = await AskJson<SiteChoice>("Ada", SelectionPrompt(), SelectionUser(), ValidateChoice, ct);
                ada.Ai.MarkDecision();
                Log($"[Llama/Ada] casas em: {string.Join(", ", choice.build_at)}{(State.farmsWanted > 0 ? $" | fazenda em: {choice.farm_at}" : "")} | motivo: \"{choice.reason}\"");
                ada.Ai.Show(AgentStatus.Idle, "acompanhando a obra");
                ada.Say(choice.reason);
                AddMessage("Ada", "Linus", choice.reason);

                // 4. Linus builds each approved site; Unity retries elsewhere if a site fills up.
                State.status = "Building";
                var jobs = choice.build_at.Select(s => ("house", s)).ToList();
                if (State.farmsWanted > 0) jobs.Add(("farm", choice.farm_at));
                foreach (var (type, site) in jobs)
                {
                    var label = type == "farm" ? "fazenda" : "casa";
                    var task = AddTask("Linus", $"construir {label} perto de {site}");
                    var target = site;
                    var built = false;
                    while (task.attempts <= MaxRetries)
                    {
                        if (builder.CountSites(Landmark.Find(target).transform.position) == 0)
                        {
                            var alt = State.sharedMemory.Where(r => r.location != target && builder.CountSites(Landmark.Find(r.location).transform.position) > 0)
                                .OrderByDescending(r => choice.build_at.Contains(r.location)).Select(r => r.location).FirstOrDefault();
                            if (alt == null) break;
                            State.recoveries++;
                            Log($"[Unity] recuperação: {target} sem espaço, tentando {alt}");
                            target = alt;
                        }
                        task.attempts++;
                        var ok = await linus.Ai.Perform($"construir {label} perto de {target}", Actions(type, ("move_to", target), ("build", target)), Log, ct);
                        ct.ThrowIfCancellationRequested();
                        if (ok) { if (type == "farm") State.farmsBuilt++; else State.housesBuilt++; built = true; break; }
                        Log($"[Unity] tentativa {task.attempts} falhou: {linus.Ai.LastResult}");
                    }
                    Finish(task, built ? "Done" : "Failed");
                }

                var any = State.housesBuilt + State.farmsBuilt > 0;
                State.status = State.housesBuilt >= State.housesWanted && State.farmsBuilt >= State.farmsWanted ? "Succeeded" : any ? "Partial" : "Failed";
                State.result = Built();
            }
            catch (OperationCanceledException)
            {
                State.status = "Cancelled";
                State.result = $"cancelada ({Built()})";
                foreach (var a in new[] { grace, linus }) a.Ai.Stop();
            }
            catch (Exception e)
            {
                State.status = State.housesBuilt + State.farmsBuilt > 0 ? "Partial" : "Failed";
                State.result = e.Message;
            }
            finally
            {
                foreach (var t in State.tasks.Where(t => t.status == "Running" || t.status == "Pending")) t.status = State.status == "Cancelled" ? "Cancelled" : "Failed";
                ada.Ai.Show(AgentStatus.Idle, "");
                State.durationSeconds = Time.realtimeSinceStartup - startedAt;
                Log($"[Unity] Missão {State.status}: {State.result}");
                ada.Say($"Missão {State.status}: {State.result}");
                State.knowledge = Merge(State.knowledge, State.sharedMemory);
                Finished?.Invoke(State);
                cts?.Dispose();
                cts = null;
            }
        }

        // --- Agent-to-agent dialogue -------------------------------------------------

        static string Facts => string.Join("; ", State.sharedMemory.Select(r => $"{r.location}: {r.freeSites} free building sites"));

        static async Task Discuss(NpcAgent grace, NpcAgent linus, CancellationToken ct)
        {
            var g = await Speak(grace, "Ada",
                "You are Grace, the explorer agent of AgentWorld. You just inspected locations for Ada, the coordinator. " +
                "Report to Ada in ONE short sentence (max 25 words) citing the real numbers given. Never invent places or numbers. " +
                "Use the same language as the mission.",
                $"Mission: {State.objective}\nYour measurements: {Facts}", ct);
            var wanted = $"{State.housesWanted} house(s)" + (State.farmsWanted > 0 ? " and 1 farm" : "");
            await Speak(linus, "Ada",
                "You are Linus, the builder agent of AgentWorld. Each house or farm needs one free building site (a 2.8 x 1.4 plot plus 1.2 clearance around it). " +
                $"Ada wants {wanted}. In ONE short sentence (max 25 words) tell Ada whether that is feasible with the free sites below and give one practical building tip " +
                "(where there is most room, spacing, or what to build first). Never invent numbers. Use the same language as the mission.",
                $"Mission: {State.objective}\nGrace said: {g ?? "(no report)"}\nFree sites: {Facts}", ct);
        }

        /// One Llama-generated line of dialogue. Failures are logged and skipped; they never fake a reply.
        static async Task<string> Speak(NpcAgent who, string to, string system, string user, CancellationToken ct)
        {
            who.Ai.Show(AgentStatus.Acting, "falando");
            try
            {
                var raw = await LlamaAgentBrain.WithTimeout(t => AgentHub.Llm.Chat(system, user, false, t), ct);
                var text = (raw ?? "").Trim().Split('\n')[0].Trim().Trim('"');
                if (text.Length > 220) text = text.Substring(0, 220);
                if (text == "") return null;
                who.Say(text);
                AddMessage(who.displayName, to, text);
                await Awaitable.WaitForSecondsAsync(1.5f, ct); // let the bubble be read
                return text;
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception e)
            {
                State.dialogueFailures++;
                Log($"[Unity] {who.displayName} não respondeu ({e.Message}); a missão continua sem essa fala");
                return null;
            }
            finally { who.Ai.Show(AgentStatus.Idle, ""); }
        }

        public const int ConversationCap = 12;

        static void AddMessage(string from, string to, string text)
        {
            State.conversation.Add(new AgentMessage { from = from, to = to, text = text });
            while (State.conversation.Count > ConversationCap) State.conversation.RemoveAt(0);
            Log($"[Llama/{from} → {to}] {text}");
        }

        /// Latest measurement per location wins.
        static List<SiteReport> Merge(List<SiteReport> older, List<SiteReport> newer)
        {
            var map = new Dictionary<string, SiteReport>();
            foreach (var r in (older ?? new List<SiteReport>()).Concat(newer ?? new List<SiteReport>())) map[r.location] = r;
            return map.Values.OrderBy(r => r.location).ToList();
        }

        // --- Llama decisions -------------------------------------------------------

        static async Task<T> AskJson<T>(string who, string system, string user, Func<T, List<string>> validate, CancellationToken ct) where T : class
        {
            var feedback = "";
            for (var attempt = 1; ; attempt++)
            {
                var raw = await LlamaAgentBrain.WithTimeout(t => AgentHub.Llm.Chat(system, user + feedback, true, t), ct);
                T value = null;
                var errors = new List<string>();
                try
                {
                    int a = raw.IndexOf('{'), b = raw.LastIndexOf('}');
                    if (a < 0 || b <= a) errors.Add("resposta sem JSON");
                    else value = JsonUtility.FromJson<T>(raw.Substring(a, b - a + 1));
                }
                catch (Exception e) { errors.Add("JSON inválido: " + e.Message); }
                if (value != null) errors.AddRange(validate(value));
                if (errors.Count == 0) return value;
                State.invalidResponses++;
                Log($"[Unity] resposta de {who} rejeitada (tentativa {attempt}/{MaxRetries}): {string.Join("; ", errors)}");
                if (attempt >= MaxRetries) throw new Exception($"{who}: plano do LLM rejeitado após {attempt} tentativas");
                feedback = $"\nYour previous answer was REJECTED: {string.Join("; ", errors)}. Return corrected JSON.";
            }
        }

        /// Small models echo prompt placeholders ("<lake>", "near lake"); normalize formatting only, never meaning.
        static string Norm(string id) => (id ?? "").Trim().Trim('<', '>', '"', '\'', ' ').ToLowerInvariant().Replace(' ', '_').Replace("near_", "");

        static List<string> Ids => Landmark.All.Where(l => l.GetComponent<BuiltStructure>() == null).Select(l => l.id).OrderBy(s => s).ToList();

        static string DelegationPrompt() =>
$@"You are Ada, the coordinator agent of AgentWorld, a 2D pixel-art village. You lead two agents:
- Grace (explorer): walks to locations and reports how many free building sites each has.
- Linus (builder): builds ONLY two things: houses and farms (fenced crop fields).
The team CANNOT: demolish or move things, build anything else (castles, bridges, roads, towers...), change terrain or water, fight, or leave the map.
Given the player's mission, decide which locations Grace must explore and how many houses and farms Linus should build.
Return ONLY JSON with keys feasible (""yes"" or ""no""), explore (list of location ids), houses (number 0-{MaxHouses}), farms (number 0-{MaxFarms}) and message (one short sentence).
Rules:
- If the mission needs something the team cannot do, return feasible ""no"" and explain why in message. Never pretend.
- explore 1 to {MaxExplore} DIFFERENT ids, only from: {string.Join(", ", Ids)}.
- Prefer locations named in the mission plus open areas next to them.
- A village means {MaxHouses} houses and 1 farm. Build at least one house or farm.
Write the message in the same language as the mission.
Example: {{""feasible"":""yes"",""explore"":[""plaza"",""east_field""],""houses"":2,""farms"":0,""message"":""Grace, check the plaza and the east field; Linus, get ready.""}}";

        static List<string> ValidateDelegation(Delegation d)
        {
            var errors = new List<string>();
            if (d.Infeasible)
            {
                if (string.IsNullOrWhiteSpace(d.message)) errors.Add("feasible=no exige uma explicação em message");
                else if (d.message.Length > 200) d.message = d.message.Substring(0, 200);
                return errors;
            }
            d.explore = (d.explore ?? new List<string>()).Select(Norm).Distinct().ToList();
            if (d.explore.Count == 0) errors.Add("explore vazio");
            if (d.explore.Count > MaxExplore) d.explore = d.explore.Take(MaxExplore).ToList();
            errors.AddRange(d.explore.Where(id => !Ids.Contains(id)).Select(id => $"local inválido '{id}'"));
            d.houses = Mathf.Clamp(d.houses, 0, MaxHouses);
            d.farms = Mathf.Clamp(d.farms, 0, AgentConfigs.Has("builder", "build_farm") ? MaxFarms : 0);
            if (d.houses + d.farms == 0) errors.Add("nada para construir: houses e farms são 0");
            if (d.message?.Length > 200) d.message = d.message.Substring(0, 200);
            return errors;
        }

        static string SelectionPrompt() =>
$@"You are Ada, the coordinator agent of AgentWorld. Grace explored locations and wrote reports to shared memory.
Choose where Linus builds exactly {State.housesWanted} house(s){(State.farmsWanted > 0 ? " and 1 farm" : "")}.
Return ONLY this JSON, e.g. {{""build_at"":[""plaza"",""plaza""],""farm_at"":""{(State.farmsWanted > 0 ? "east_field" : "")}"",""reason"":""The plaza has the most free land.""}}
Rules:
- build_at (one id per house){(State.farmsWanted > 0 ? " and farm_at" : "")} may ONLY use these ids: {string.Join(", ", State.sharedMemory.Where(r => r.freeSites > 0).Select(r => r.location))}.
- A location may be used at most as many times as its free sites (houses and farm together).{(State.farmsWanted > 0 ? "" : "\n- Leave farm_at empty.")}
- If the mission names a place (e.g. ""near the lake"") and it has free sites, put the houses there first.
Write the reason in the same language as the mission.";

        static string SelectionUser() =>
            $"Mission: {State.objective}\n" +
            (State.conversation.Count > 1 ? "Team discussion:\n" + string.Join("\n", State.conversation.Skip(1).Select(m => $"{m.from}: {m.text}")) + "\n" : "") +
            "Shared memory (Grace's reports):\n" +
            string.Join("\n", State.sharedMemory.Select(r => $"- location id: {r.location} | free sites: {r.freeSites} | landmarks close by (not buildable ids): {(r.nearby == "" ? "none" : r.nearby)}"));

        static List<string> ValidateChoice(SiteChoice c)
        {
            var errors = new List<string>();
            c.build_at = (c.build_at ?? new List<string>()).Select(Norm).Where(s => s != "").Take(State.housesWanted).ToList();
            if (State.housesWanted > 0 && c.build_at.Count == 0) errors.Add("build_at vazio");
            c.farm_at = State.farmsWanted > 0 ? Norm(c.farm_at) : null;
            if (State.farmsWanted > 0 && c.farm_at == "") errors.Add("farm_at vazio");
            var uses = c.farm_at == null || c.farm_at == "" ? c.build_at : c.build_at.Append(c.farm_at).ToList();
            foreach (var g in uses.GroupBy(s => s))
            {
                var r = State.sharedMemory.FirstOrDefault(x => x.location == g.Key);
                if (r == null) errors.Add($"'{g.Key}' não foi explorado");
                else if (g.Count() > r.freeSites) errors.Add($"'{g.Key}' só tem {r.freeSites} terrenos livres");
            }
            if (string.IsNullOrWhiteSpace(c.reason)) c.reason = "Locais escolhidos.";
            return errors;
        }

        // --- Helpers ---------------------------------------------------------------

        static List<AgentAction> Actions(params (string type, string loc)[] steps) => Actions("house", steps);

        static List<AgentAction> Actions(string structure, params (string type, string loc)[] steps) => steps.Select(s =>
            s.type == "build" ? new AgentAction { type = "build", structure = structure, location = s.loc } : new AgentAction { type = s.type, target = s.loc }).ToList();

        static string Built() =>
            $"{State.housesBuilt}/{State.housesWanted} casas" + (State.farmsWanted > 0 ? $", {State.farmsBuilt}/{State.farmsWanted} fazenda" : "") + " construídas";

        static MissionTask AddTask(string agent, string description)
        {
            var t = new MissionTask { id = State.tasks.Count + 1, agent = agent, description = description, status = "Running" };
            State.tasks.Add(t);
            return t;
        }

        static void Finish(MissionTask t, string status) => t.status = status;

        static void Log(string line)
        {
            State.log.Add(line);
            while (State.log.Count > LogCap) State.log.RemoveAt(0);
            output(line);
            Debug.Log("[mission] " + line);
        }

        public static MissionState Capture()
        {
            var copy = JsonUtility.FromJson<MissionState>(JsonUtility.ToJson(State));
            if (Live.Contains(copy.status)) copy.status = "Interrupted"; // missions are not resumed after load
            return copy;
        }

        public static void Restore(MissionState s)
        {
            Stop();
            State = s ?? new MissionState();
            if (Live.Contains(State.status)) State.status = "Interrupted";
        }
    }
}
